public extension View {
    /// Applies font, Figma line height, underline and strikethrough of a text style.
    func dsTextStyle(_ style: DSTextStyle) -> some View {
        modifier(DSTextStyleModifier(style: style))
    }
}

struct DSTextStyleModifier: ViewModifier {
    let style: DSTextStyle

    private var fontLineHeight: CGFloat {
        #if canImport(UIKit)
        return (UIFont(name: DSTypography.fontFamily, size: style.size) ?? .systemFont(ofSize: style.size)).lineHeight
        #else
        return style.size * 1.2
        #endif
    }

    func body(content: Content) -> some View {
        let extra = max(0, style.lineHeight - fontLineHeight)
        return content
            .font(style.font)
            .lineSpacing(extra)
            .padding(.vertical, extra / 2)
            .underline(style.underline)
            .strikethrough(style.strikethrough)
    }
}

// MARK: - Shadow

public struct DSShadowLayer {
    public let color: Color
    public let x: CGFloat
    public let y: CGFloat
    /// Figma blur radius. SwiftUI's radius is roughly half of it.
    public let blur: CGFloat
    /// SwiftUI shadows have no spread; kept for reference.
    public let spread: CGFloat
}

public enum DSShadow {
    public static let base: [DSShadowLayer] = [
        DSShadowLayer(color: Color(dsRGBA: 0x000000, alpha: 0.02), x: 0, y: 2, blur: 4, spread: 0),
        DSShadowLayer(color: Color(dsRGBA: 0x000000, alpha: 0.02), x: 0, y: 1, blur: 6, spread: -1),
        DSShadowLayer(color: Color(dsRGBA: 0x000000, alpha: 0.031), x: 0, y: 1, blur: 2, spread: 0)
    ]
    public static let secondary: [DSShadowLayer] = [
        DSShadowLayer(color: Color(dsRGBA: 0x000000, alpha: 0.051), x: 0, y: 9, blur: 28, spread: 8),
        DSShadowLayer(color: Color(dsRGBA: 0x000000, alpha: 0.122), x: 0, y: 3, blur: 6, spread: -4),
        DSShadowLayer(color: Color(dsRGBA: 0x000000, alpha: 0.078), x: 0, y: 6, blur: 16, spread: 0)
    ]
    public static let tertiary: [DSShadowLayer] = [
        DSShadowLayer(color: Color(dsRGBA: 0x000000, alpha: 0.02), x: 0, y: 2, blur: 4, spread: 0),
        DSShadowLayer(color: Color(dsRGBA: 0x000000, alpha: 0.02), x: 0, y: 1, blur: 6, spread: -1),
        DSShadowLayer(color: Color(dsRGBA: 0x000000, alpha: 0.031), x: 0, y: 1, blur: 2, spread: 0)
    ]
}

public extension View {
    func dsShadow(_ layers: [DSShadowLayer]) -> some View {
        layers.reduce(AnyView(self)) { view, layer in
            AnyView(view.shadow(color: layer.color, radius: layer.blur / 2, x: layer.x, y: layer.y))
        }
    }
}

// MARK: - Helpers

extension Color {
    init(dsRGBA hex: UInt32, alpha: Double = 1) {
        self.init(.sRGB,
                  red: Double((hex >> 16) & 0xFF) / 255,
                  green: Double((hex >> 8) & 0xFF) / 255,
                  blue: Double(hex & 0xFF) / 255,
                  opacity: alpha)
    }

    init(dsLight light: UInt32, dark: UInt32) {
        #if canImport(UIKit)
        self.init(uiColor: UIColor { traits in
            UIColor(Color(dsRGBA: traits.userInterfaceStyle == .dark ? dark : light))
        })
        #else
        self.init(dsRGBA: light)
        #endif
    }
}
